#!/usr/bin/env bash
# Build both legs of an E3 cell.
#
#   build_cell.sh <cell_dir> alive2|saw <key> <cell_id> [checker_result]
#
# key is checksig or cms (selects the C/L source pair).
# L handlers: twin_ops.h is generated by cells/_tools/mk_leaf.py from
# twin/ops_ir.py purely for State/Stack/error types and core_ord().  The
# CHECKSIG/CHECKMULTISIG handler itself is NOT in ops_ir.py; l_*.cpp is a
# reviewed transliteration (see spec.md trust_note).
set -euo pipefail

CELL_DIR="$1"; MODE="$2"; KEY="$3"; ID="$4"; CHECKER="${5:-0}"
E3="$(cd "$(dirname "$0")" && pwd)"
CELLS="$(cd "$E3/../.." && pwd)"
EQ="$(cd "$CELLS/.." && pwd)"
BUILD="$CELL_DIR/build"
mkdir -p "$BUILD"

python3 "$CELLS/_tools/mk_leaf.py" \
  --ops OP_UNSUPPORTED_CHECKSIG --max-depth 6 --max-elem 2 \
  --out "$BUILD/twin_ops.h" --meta "$BUILD/twin_ops.meta.json" 2>/dev/null
python3 "$CELLS/_tools/mk_leaf.py" \
  --ops OP_UNSUPPORTED_CHECKSIG --max-depth 6 --max-elem 2 \
  --check "$BUILD/twin_ops.h" 2>/dev/null

if [ "$KEY" = "checksig" ]; then
  CGLOB=c_checksig.cpp; LGLOB=l_checksig.cpp
else
  CGLOB=c_cms.cpp; LGLOB=l_cms.cpp
fi

CXX=(/usr/bin/clang++-20 -std=c++17 -I "$E3" -I "$BUILD"
     -fno-discard-value-names -fno-strict-aliasing)
LLVM=/usr/lib/llvm-20/bin

if [ "$MODE" = "alive2" ]; then
  # External-declaration lane: both modules call @btc_equiv_check_sig.
  "${CXX[@]}" -O1 -S -emit-llvm "$E3/$CGLOB" -o "$BUILD/c_leaf.ll"
  "${CXX[@]}" -O1 -S -emit-llvm "$E3/$LGLOB" -o "$BUILD/l_leaf.ll"
  {
    printf 'mode=alive2 key=%s\n' "$KEY"
    printf 'clang=%s\n' "$(/usr/bin/clang++-20 --version | head -1)"
    printf 'llvm=%s\n' "$("$LLVM/llvm-extract" --version | head -1)"
    printf 'twin_ops_sha256=%s\n' "$(sha256sum "$BUILD/twin_ops.h" | cut -d' ' -f1)"
    printf 'c_leaf_sha256=%s\n' "$(sha256sum "$BUILD/c_leaf.ll" | cut -d' ' -f1)"
    printf 'l_leaf_sha256=%s\n' "$(sha256sum "$BUILD/l_leaf.ll" | cut -d' ' -f1)"
  } > "$BUILD/build.txt"
else
  # SAW lane: shared stub definition linked into BOTH modules; -O0 keeps the
  # call and branch structure visible for concrete closed scenarios.
  "${CXX[@]}" -O0 -c -emit-llvm "$E3/$CGLOB" -o "$BUILD/c_leaf.bc"
  "${CXX[@]}" -O0 -c -emit-llvm "$E3/$LGLOB" -o "$BUILD/l_leaf.bc"
  "${CXX[@]}" -O0 -c -emit-llvm -DBTC_EQUIV_CHECKER_RESULT="$CHECKER" \
    "$E3/checker_stub.cpp" -o "$BUILD/checker_stub_${CHECKER}.bc"
  "$LLVM/llvm-link" "$BUILD/c_leaf.bc" "$BUILD/checker_stub_${CHECKER}.bc" \
    -o "$BUILD/c_leaf_saw_${CHECKER}.bc"
  "$LLVM/llvm-link" "$BUILD/l_leaf.bc" "$BUILD/checker_stub_${CHECKER}.bc" \
    -o "$BUILD/l_leaf_saw_${CHECKER}.bc"
  "$LLVM/llvm-dis" "$BUILD/c_leaf_saw_${CHECKER}.bc" -o "$BUILD/c_leaf_saw_${CHECKER}.ll"
  "$LLVM/llvm-dis" "$BUILD/l_leaf_saw_${CHECKER}.bc" -o "$BUILD/l_leaf_saw_${CHECKER}.ll"
  python3 "$E3/oracle.py" "$KEY" "$BUILD/scenarios_${CHECKER}.json" "$CHECKER" >/dev/null
  {
    printf 'mode=saw checker_result=%s key=%s\n' "$CHECKER" "$KEY"
    printf 'clang=%s\n' "$(/usr/bin/clang++-20 --version | head -1)"
    printf 'llvm=%s\n' "$("$LLVM/llvm-link" --version | head -1)"
    printf 'twin_ops_sha256=%s\n' "$(sha256sum "$BUILD/twin_ops.h" | cut -d' ' -f1)"
    printf 'c_bc_sha256=%s\n' "$(sha256sum "$BUILD/c_leaf_saw_${CHECKER}.bc" | cut -d' ' -f1)"
    printf 'l_bc_sha256=%s\n' "$(sha256sum "$BUILD/l_leaf_saw_${CHECKER}.bc" | cut -d' ' -f1)"
  } > "$BUILD/build_saw_${CHECKER}.txt"
fi
